CREATE TABLE IF NOT EXISTS "member_user"
(
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY COMMENT '编号',
    "nickname"    varchar(30)  NOT NULL DEFAULT '' COMMENT '用户昵称',
    "name"        varchar(30)  NULL COMMENT '真实名字',
    sex           tinyint      null comment '性别',
    birthday      datetime     null comment '出生日期',
    area_id       int          null comment '所在地',
    mark          varchar(255) null comment '用户备注',
    point         int                   default 0 null comment '积分',
    "avatar"      varchar(255) NOT NULL DEFAULT '' COMMENT '头像',
    company       varchar(64)  null comment '公司名称（微信扫码登录补全时采集，选填）',
    "status"      tinyint      NOT NULL COMMENT '状态',
    "mobile"      varchar(11)  NOT NULL COMMENT '手机号',
    "email"       varchar(50)  NULL COMMENT '邮箱',
    "password"    varchar(100) NOT NULL DEFAULT '' COMMENT '密码',
    "register_ip" varchar(32)  NOT NULL COMMENT '注册 IP',
    "register_terminal" tinyint NULL DEFAULT 0 COMMENT '注册终端',
    "login_ip"    varchar(50)  NULL     DEFAULT '' COMMENT '最后登录IP',
    "login_date"  datetime     NULL     DEFAULT NULL COMMENT '最后登录时间',
    "tag_ids"     varchar(255) NULL     DEFAULT NULL COMMENT '用户标签编号列表,以逗号分隔',
    "level_id"    bigint       NULL     DEFAULT NULL COMMENT '等级编号',
    "experience"  bigint       NULL     DEFAULT NULL COMMENT '经验',
    "group_id"    bigint       NULL     DEFAULT NULL COMMENT '用户分组编号',
    "creator"     varchar(64)  NULL     DEFAULT '' COMMENT '创建者',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    "updater"     varchar(64)  NULL     DEFAULT '' COMMENT '更新者',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    "deleted"     bit(1)       NOT NULL DEFAULT '0' COMMENT '是否删除',
    "tenant_id"   bigint       not null default '0',
    PRIMARY KEY ("id")
) COMMENT '会员表';

CREATE TABLE IF NOT EXISTS "member_address" (
    "id" bigint(20) NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint(20) NOT NULL,
    "name" varchar(64) NOT NULL,
    "mobile" varchar(20) NOT NULL,
    "area_id" bigint(20) NOT NULL,
    "detail_address" varchar(250) NOT NULL,
    "default_status" bit NOT NULL,
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "updater" varchar(64) DEFAULT '',
    PRIMARY KEY ("id")
) COMMENT '用户收件地址';

CREATE TABLE IF NOT EXISTS "member_tag"
(
    "id"          bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"        varchar  NOT NULL,
    "creator"     varchar           DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar           DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit      NOT NULL DEFAULT FALSE,
    "tenant_id"   bigint   NOT NULL default '0',
    PRIMARY KEY ("id")
) COMMENT '会员标签';

CREATE TABLE IF NOT EXISTS "member_level"
(
    "id"             bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"           varchar  NOT NULL,
    "experience"     int      NOT NULL,
    "level"          int      NOT NULL,
    "discount_percent"       int      NOT NULL,
    "icon"           varchar  NOT NULL,
    "background_url" varchar  NOT NULL,
    "creator"        varchar           DEFAULT '',
    "create_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar           DEFAULT '',
    "update_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit      NOT NULL DEFAULT FALSE,
    "tenant_id"      bigint   not null default '0',
    "status" tinyint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT '会员等级';

CREATE TABLE IF NOT EXISTS "member_group"
(
    "id"          bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"        varchar  NOT NULL,
    "remark"      varchar  NOT NULL,
    "status" tinyint NOT NULL DEFAULT '0',
    "creator"     varchar           DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar           DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit      NOT NULL DEFAULT FALSE,
    "tenant_id"      bigint   not null default '0',
    PRIMARY KEY ("id")
) COMMENT '用户分组';
CREATE TABLE IF NOT EXISTS "member_brokerage_record"
(
    "id"            int      NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"       bigint   NOT NULL,
    "biz_id"        varchar  NOT NULL,
    "biz_type"      varchar  NOT NULL,
    "title"         varchar  NOT NULL,
    "price"         int      NOT NULL,
    "total_price"   int      NOT NULL,
    "description"   varchar  NOT NULL,
    "status"        varchar  NOT NULL,
    "frozen_days"   int      NOT NULL,
    "unfreeze_time" varchar,
    "creator"       varchar           DEFAULT '',
    "create_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar           DEFAULT '',
    "update_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit      NOT NULL DEFAULT FALSE,
    "tenant_id"      bigint   not null default '0',
    PRIMARY KEY ("id")
) COMMENT '佣金记录';

CREATE TABLE IF NOT EXISTS "member_subscription"
(
    "id"                    bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id"             bigint   NOT NULL,
    "plan_id"               bigint   NOT NULL,
    "edition"               varchar(16) NULL DEFAULT NULL,
    "spu_id"                bigint   NOT NULL,
    "sku_id"                bigint   NOT NULL,
    "period_months"         int      NOT NULL,
    "start_time"            datetime NOT NULL,
    "end_time"              datetime NOT NULL,
    "source_order_id"       bigint   NOT NULL,
    "source_order_item_id"  bigint   NOT NULL,
    "source_order_no"       varchar(64) NOT NULL,
    "refunded"              bit      NOT NULL DEFAULT FALSE,
    "creator"               varchar           DEFAULT '',
    "create_time"           datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"               varchar           DEFAULT '',
    "update_time"           datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"               bit      NOT NULL DEFAULT FALSE,
    "tenant_id"             bigint   NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "source_order_item_id")
) COMMENT 'MaxLabel 会员订阅授予流水';

CREATE TABLE IF NOT EXISTS "maxlabel_label_template"
(
    "id"           bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id"    bigint NOT NULL,
    "name"         varchar(255) NOT NULL,
    "content"      clob NOT NULL,
    "size_bytes"   int NOT NULL,
    "content_hash" char(64) NOT NULL,
    "width_mm"     decimal(10,2) NOT NULL DEFAULT 0,
    "height_mm"    decimal(10,2) NOT NULL DEFAULT 0,
    "category"     varchar(64) DEFAULT '',
    "keywords"     varchar(255) DEFAULT '',
    "creator"      varchar DEFAULT '',
    "create_time"  datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"      varchar DEFAULT '',
    "update_time"  datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"      bit NOT NULL DEFAULT FALSE,
    "tenant_id"    bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'MaxLabel 会员私有云端模板';

CREATE TABLE IF NOT EXISTS "maxlabel_shared_template"
(
    "id"                  bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "source_template_id"  bigint NOT NULL,
    "publisher_member_id" bigint NOT NULL,
    "name"                varchar(255) NOT NULL,
    "content"             clob NOT NULL,
    "size_bytes"          int NOT NULL,
    "width_mm"            decimal(10,2) NOT NULL DEFAULT 0,
    "height_mm"           decimal(10,2) NOT NULL DEFAULT 0,
    "category"            varchar(64) DEFAULT '',
    "keywords"            varchar(255) DEFAULT '',
    "audit_status"        tinyint NOT NULL DEFAULT 0,
    "reject_reason"       varchar(255),
    "audit_user_id"       bigint,
    "audit_time"          datetime,
    "published_time"      datetime,
    "creator"             varchar DEFAULT '',
    "create_time"         datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"             varchar DEFAULT '',
    "update_time"         datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"             bit NOT NULL DEFAULT FALSE,
    "tenant_id"           bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "source_template_id")
) COMMENT 'MaxLabel 平台共享模板';

CREATE TABLE IF NOT EXISTS "maxlabel_print_record"
(
    "id"              bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id"       bigint NOT NULL,
    "device_id"       char(36) NOT NULL,
    "record_uid"      char(36) NOT NULL,
    "print_time"      datetime NOT NULL,
    "template_title"  varchar(255) NOT NULL,
    "mode"            varchar(16) NOT NULL,
    "count"           int NOT NULL,
    "copies"          int NOT NULL,
    "physical_count"  bigint,
    "sent_count"      bigint,
    "status"          varchar(16) NOT NULL,
    "printer"         varchar(255) NOT NULL DEFAULT '',
    "creator"         varchar DEFAULT '',
    "create_time"     datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar DEFAULT '',
    "update_time"     datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"         bit NOT NULL DEFAULT FALSE,
    "tenant_id"       bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "member_id", "record_uid")
) COMMENT 'MaxLabel 会员打印记录';

CREATE TABLE IF NOT EXISTS "maxlabel_org"
(
    "id"              bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"            varchar(128) NOT NULL,
    "owner_member_id" bigint NOT NULL,
    "status"          tinyint NOT NULL DEFAULT 0,
    "remark"          varchar(255) DEFAULT '',
    "creator"         varchar DEFAULT '',
    "create_time"     datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar DEFAULT '',
    "update_time"     datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"         bit NOT NULL DEFAULT FALSE,
    "tenant_id"       bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'MaxLabel 企业主体';

CREATE TABLE IF NOT EXISTS "maxlabel_org_member"
(
    "id"          bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "org_id"      bigint NOT NULL,
    "member_id"   bigint NOT NULL,
    "role"        tinyint NOT NULL DEFAULT 3,
    "joined_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator"     varchar DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"     bit NOT NULL DEFAULT FALSE,
    "tenant_id"   bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "member_id")
) COMMENT 'MaxLabel 企业成员关系';

CREATE TABLE IF NOT EXISTS "maxlabel_org_license"
(
    "id"                   bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "org_id"               bigint NOT NULL,
    "plan_id"              bigint NOT NULL,
    "edition"              varchar(16) NULL DEFAULT NULL,
    "spu_id"               bigint NOT NULL,
    "sku_id"               bigint NOT NULL,
    "period_months"        int NOT NULL,
    "seats_total"          int NOT NULL,
    "start_time"           datetime NOT NULL,
    "end_time"             datetime NOT NULL,
    "source_order_id"      bigint NOT NULL,
    "source_order_item_id" bigint NOT NULL,
    "source_order_no"      varchar(64) NOT NULL,
    "refunded"             bit NOT NULL DEFAULT FALSE,
    "folded_time"          datetime NULL DEFAULT NULL,
    "creator"              varchar DEFAULT '',
    "create_time"          datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"              varchar DEFAULT '',
    "update_time"          datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"              bit NOT NULL DEFAULT FALSE,
    "tenant_id"            bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "source_order_item_id")
) COMMENT 'MaxLabel 企业授权批次';

CREATE TABLE IF NOT EXISTS "maxlabel_org_seat"
(
    "id"            bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "org_id"        bigint NOT NULL,
    "member_id"     bigint NOT NULL,
    "status"        tinyint NOT NULL DEFAULT 0,
    "operator_type" tinyint NOT NULL DEFAULT 1,
    "operator_id"   bigint NOT NULL DEFAULT 0,
    "assigned_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "revoked_time"  datetime,
    "creator"       varchar DEFAULT '',
    "create_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar DEFAULT '',
    "update_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"       bit NOT NULL DEFAULT FALSE,
    "tenant_id"     bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "org_id", "member_id")
) COMMENT 'MaxLabel 企业席位分配';
